// Validate required input parameters
const input = $input.first().json;
const body = input.body || {};

const guildId = body.guild_id;
const userId = body.user_id;
const threadId = body.thread_id || null;
const period = body.period || 'week';
const includeHelpRequests = body.include_help_requests !== false;

// Validate required fields
const errors = [];
if (!guildId) errors.push('guild_id is required');
if (!userId) errors.push('user_id is required');

// Validate period value
const validPeriods = ['week', 'month', 'all'];
if (!validPeriods.includes(period)) {
  errors.push(`period must be one of: ${validPeriods.join(', ')}`);
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join('; '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Calculate date range based on period
const now = new Date();
let startDate;
switch (period) {
  case 'week':
    startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    break;
  case 'month':
    startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    break;
  case 'all':
    startDate = new Date(0); // Beginning of time
    break;
}

return [{
  json: {
    valid: true,
    guild_id: guildId,
    user_id: userId,
    thread_id: threadId,
    period: period,
    include_help_requests: includeHelpRequests,
    start_date: startDate.toISOString(),
    start_timestamp: startDate.getTime(),
    request_timestamp: now.getTime()
  }
}];

// Process conversation history from Redis
const redisResult = $input.first().json;
const validatedInput = $('Validate Input').first().json;

const startTimestamp = validatedInput.start_timestamp;
const period = validatedInput.period;

// Parse Redis result
let rawHistory = [];
try {
  const redisValue = redisResult.propertyName || redisResult.value || redisResult;
  if (redisValue && redisValue !== 'null' && redisValue !== null) {
    rawHistory = typeof redisValue === 'string' ? JSON.parse(redisValue) : redisValue;
    if (!Array.isArray(rawHistory)) rawHistory = [];
  }
} catch (e) {
  rawHistory = [];
}

// Filter by period
const filteredHistory = period === 'all' 
  ? rawHistory 
  : rawHistory.filter(msg => {
      const msgTime = new Date(msg.timestamp || msg.created_at || 0).getTime();
      return msgTime >= startTimestamp;
    });

// Extract subjects and topics from messages
const subjects = new Set();
const topics = [];
let questionCount = 0;

filteredHistory.forEach(msg => {
  // Extract subjects from metadata or content analysis
  if (msg.subject) subjects.add(msg.subject);
  if (msg.metadata?.subject) subjects.add(msg.metadata.subject);

  // Count questions (messages from user)
  if (msg.role === 'user' || msg.type === 'user') {
    questionCount++;
  }

  // Extract topics
  if (msg.topic) topics.push(msg.topic);
  if (msg.metadata?.topic) topics.push(msg.metadata.topic);
});

// Format history for LLM
const formattedHistory = filteredHistory.map(msg => {
  const role = msg.role || msg.type || 'user';
  const content = msg.content || msg.message || msg.text || '';
  const timestamp = msg.timestamp || msg.created_at || '';
  return `[${timestamp}] ${role}: ${content}`;
}).join('\n');

return [{
  json: {
    ...validatedInput,
    history: formattedHistory,
    history_count: filteredHistory.length,
    questions_count: questionCount,
    subjects_detected: Array.from(subjects),
    topics_detected: [...new Set(topics)],
    raw_messages: filteredHistory.slice(0, 50) // Limit for context
  }
}];

// Merge help requests with history data
const helpResponse = $input.first().json;
const historyData = $('Process History').first().json;

// Parse help requests
let helpRequests = [];
let helpRequestsCount = 0;

try {
  if (helpResponse && !helpResponse.error) {
    const data = helpResponse.data || helpResponse.help_requests || helpResponse;
    if (Array.isArray(data)) {
      helpRequests = data;
      helpRequestsCount = data.length;
    }
  }
} catch (e) {
  helpRequests = [];
}

// Format help requests for LLM
const formattedHelpRequests = helpRequests.map(req => {
  const subject = req.subject || 'Non specifie';
  const question = req.question || req.content || '';
  const status = req.status || 'pending';
  const created = req.created_at || req.timestamp || '';
  return `- [${created}] Matiere: ${subject} | Question: ${question} | Statut: ${status}`;
}).join('\n');

return [{
  json: {
    ...historyData,
    help_requests: formattedHelpRequests,
    help_requests_count: helpRequestsCount,
    help_requests_raw: helpRequests.slice(0, 20)
  }
}];

// Skip help requests, just pass through history data
const historyData = $('Process History').first().json;

return [{
  json: {
    ...historyData,
    help_requests: '',
    help_requests_count: 0,
    help_requests_raw: []
  }
}];

