        difficulty_areas: [],
        strengths: [],
        progression_notes: '',
        summary: content,
        recommendations: []
      };
    }

    // Get token usage
    if (llmResponse.usage) {
      inputTokens = llmResponse.usage.input_tokens;
      outputTokens = llmResponse.usage.output_tokens;
    }
    model = llmResponse.model || model;
  } else {
    llmError = 'No content in LLM response';
  }
